// ─────────────────────────── runtime tests ───────────────────────────────

const base: Settings = { theme: 'dark', fontSize: 14, autosave: true };

test('applies the fields the patch names', () => {
  eq(updateSettings(base, { fontSize: 18 }), {
    theme: 'dark',
    fontSize: 18,
    autosave: true,
  });
});

test('an empty patch changes nothing', () => {
  eq(updateSettings(base, {}), base);
});

test('applies several fields at once', () => {
  eq(updateSettings(base, { theme: 'light', autosave: false }), {
    theme: 'light',
    fontSize: 14,
    autosave: false,
  });
});

test('does not mutate the settings it was given', () => {
  updateSettings(base, { fontSize: 99 });
  eq(base.fontSize, 14);
});

test('treats an explicit undefined as "no change"', () => {
  const next = updateSettings(base, { fontSize: undefined });
  eq(next.fontSize, 14);
  ok('fontSize' in next);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<
    SettingsPatch,
    { theme?: 'light' | 'dark'; fontSize?: number; autosave?: boolean }
  >
>;
type _t2 = Expect<Equal<ReturnType<typeof updateSettings>, Settings>>;

function _typeTests() {
  updateSettings(base, {});
  updateSettings(base, { theme: 'light' });

  const theme: 'light' | 'dark' = updateSettings(base, {}).theme;
  use(theme);

  // @ts-expect-error — colour is not a setting
  updateSettings(base, { colour: 'red' });

  // @ts-expect-error — fontSize is optional, not free-typed
  updateSettings(base, { fontSize: 'big' });

  // @ts-expect-error — the RESULT is a full Settings, nothing optional
  const incomplete: Settings = { theme: 'dark', fontSize: 14 };
  use(incomplete);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('fills in every missing field', () => {
  eq(resolveConfig({}), { host: 'localhost', port: 8080, retries: 3 });
});

test('keeps the fields that were supplied', () => {
  eq(resolveConfig({ port: 3000 }), {
    host: 'localhost',
    port: 3000,
    retries: 3,
  });
});

test('keeps a zero — it is a value, not a missing field', () => {
  eq(resolveConfig({ retries: 0 }).retries, 0);
});

test('freezeConfig really freezes', () => {
  const frozen = freezeConfig(resolveConfig({}));
  ok(Object.isFrozen(frozen));
});

test('writing to a frozen config throws in module code', () => {
  const frozen = freezeConfig(resolveConfig({})) as { port: number };
  throws(() => {
    frozen.port = 1;
  });
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<ResolvedConfig, { host: string; port: number; retries: number }>
>;
type _t2 = Expect<
  Equal<
    FrozenConfig,
    { readonly host: string; readonly port: number; readonly retries: number }
  >
>;

function _typeTests() {
  // the whole point: no `?? 8080` needed downstream
  const port: number = resolveConfig({}).port;
  use(port);

  const frozen = freezeConfig(resolveConfig({}));

  // @ts-expect-error — a frozen config is read-only
  frozen.port = 9;

  // @ts-expect-error — a raw config still has holes; it is not resolved
  const wrong: ResolvedConfig = {} as RawConfig;
  use(wrong);

  // @ts-expect-error — resolved means every key is present
  const partial: ResolvedConfig = { host: 'localhost', port: 1 };
  use(partial);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const ada: User = {
  id: 'u1',
  name: 'Ada',
  email: 'ada@example.com',
  passwordHash: 'x'.repeat(16),
  role: 'admin',
  createdAt: '1843-01-01',
};

test('the public view keeps the harmless fields', () => {
  eq(toPublicUser(ada), {
    id: 'u1',
    name: 'Ada',
    role: 'admin',
    createdAt: '1843-01-01',
  });
});

test('the public view carries no secrets at all', () => {
  const pub = toPublicUser(ada) as Record<string, unknown>;
  ok(!('passwordHash' in pub));
  ok(!('email' in pub));
});

test('the summary is exactly two fields', () => {
  eq(toSummary(ada), { id: 'u1', name: 'Ada' });
});

test('neither view mutates the user', () => {
  toPublicUser(ada);
  toSummary(ada);
  eq(ada.email, 'ada@example.com');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<
    PublicUser,
    {
      id: string;
      name: string;
      role: 'admin' | 'member';
      createdAt: string;
    }
  >
>;
type _t2 = Expect<Equal<UserSummary, { id: string; name: string }>>;
type _t3 = Expect<
  Equal<Credentials, { email: string; passwordHash: string }>
>;
type _t4 = Expect<Equal<keyof PublicUser, 'id' | 'name' | 'role' | 'createdAt'>>;

function _typeTests() {
  const pub = toPublicUser(ada);
  const role: 'admin' | 'member' = pub.role;
  use(role);

  // @ts-expect-error — the hash is gone from the type, not just the object
  pub.passwordHash;

  // @ts-expect-error — and so is the email
  pub.email;

  // @ts-expect-error — the summary really is only id + name
  toSummary(ada).role;

  // @ts-expect-error — Credentials is only the two secret fields
  const creds: Credentials = { email: 'a@b.c', passwordHash: 'h', name: 'x' };
  use(creds);
}
use(_typeTests);

