type _t1 = Expect<
  Equal<MyPartial<{ a: string; b?: number }>, { a?: string; b?: number }>
>;
type _t2 = Expect<
  Equal<MyRequired<{ a?: string; b: number }>, { a: string; b: number }>
>;
// homomorphic: the loop runs over `keyof T`, so readonly survives it
type _t3 = Expect<
  Equal<MyPartial<{ readonly a: string }>, { readonly a?: string }>
>;
type _t4 = Expect<
  Equal<MyRequired<{ readonly a?: string }>, { readonly a: string }>
>;
// -? removes `undefined` from the value type, not just the question mark
type _t5 = Expect<
  Equal<MyRequired<{ a?: string | null }>, { a: string | null }>
>;
type _t6 = Expect<Equal<MyPartial<Draft>, Partial<Draft>>>;
type _t7 = Expect<Equal<MyRequired<DraftPatch>, Required<DraftPatch>>>;

function _typeTests() {
  summarize({});
  summarize({ title: 'Hi' });
  wordCount({ title: 't', body: 'b', tags: [] });

  // @ts-expect-error — every key of a required draft must be present
  const gap: MyRequired<DraftPatch> = { title: 'x' };
  use(gap);

  // @ts-expect-error — optional does not mean untyped
  summarize({ title: 42 });

  // @ts-expect-error — the body is not optional once -? has run
  wordCount({ title: 't', tags: [] });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('freezePoint keeps the coordinates', () => {
  eq(freezePoint({ x: 1, y: 2 }), { x: 1, y: 2 });
});

test('freezePoint freezes at runtime too', () => {
  const frozen = freezePoint({ x: 1, y: 2 }) as Point;
  ok(Object.isFrozen(frozen));
  throws(() => {
    frozen.x = 9;
  });
});

test('freezePoint copies — the caller keeps a writable original', () => {
  const original = { x: 1, y: 2 };
  freezePoint(original);
  ok(!Object.isFrozen(original));
});

test('thaw returns a writable copy', () => {
  const frozen = freezePoint({ x: 1, y: 2 });
  const copy = thaw(frozen);
  copy.x = 9;
  eq(copy, { x: 9, y: 2 });
  ok(!Object.isFrozen(copy));
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<
    MyReadonly<{ a: string; b?: number }>,
    { readonly a: string; readonly b?: number }
  >
>;
type _t2 = Expect<
  Equal<
    Mutable<{ readonly a: string; readonly b?: number }>,
    { a: string; b?: number }
  >
>;
type _t3 = Expect<Equal<Mutable<MyReadonly<Point>>, Point>>;
type _t4 = Expect<Equal<MyReadonly<Point>, Readonly<Point>>>;
// adding readonly twice is not an error and changes nothing
type _t5 = Expect<Equal<MyReadonly<MyReadonly<Point>>, MyReadonly<Point>>>;

function _typeTests() {
  const frozen = freezePoint({ x: 1, y: 2 });
  const x: number = frozen.x;
  use(x);

  // @ts-expect-error — a frozen point rejects writes at compile time
  frozen.x = 9;

  thaw(frozen).y = 4; // ...and the thawed copy accepts them

  // readonly is SHALLOW: the nested object is still writable
  const nested: MyReadonly<{ inner: { n: number } }> = { inner: { n: 1 } };
  nested.inner.n = 2;

  // @ts-expect-error — but the top-level key itself is locked
  nested.inner = { n: 3 };
}
use(_typeTests);

